Split the text into lines, split each line on the first =, and use the two halves as a key and a value.

code:
function parseEnv(text) {
  const result = {};
  const lines = text.split("\n");
  for (const line of lines) {
    const parts = line.split("=");
    result[parts[0]] = parts[1];
  }
  return result;
}
const text = "PORT=3000\nHOST=localhost";
const config = parseEnv(text);
console.log(config);
console.log("PORT is", config["PORT"]);

output:
{ PORT: '3000', HOST: 'localhost' }
PORT is 3000

Trim each line first, then skip the ones that are empty or start with a hash before splitting on the equals sign.

code:
function parseEnv(text) {
  const result = {};
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) {
      continue;
    }
    const parts = line.split("=");
    result[parts[0]] = parts[1];
  }
  return result;
}
const text = "# server config\nPORT=3000\n\nHOST=localhost";
console.log(parseEnv(text));

output:
{ PORT: '3000', HOST: 'localhost' }

trim clears the edges, and a single pair of quote characters can be peeled off with slice once you have checked for them.

code:
function clean(value) {
  let out = value.trim();
  if (out.startsWith("\"") && out.endsWith("\"")) {
    out = out.slice(1, -1);
  }
  return out;
}
function parseEnv(text) {
  const result = {};
  for (const raw of text.split("\n")) {
    const parts = raw.split("=");
    result[clean(parts[0])] = clean(parts[1]);
  }
  return result;
}
console.log(parseEnv(" NAME = \"ana\" \n ROLE = tester "));

output:
{ NAME: 'ana', ROLE: 'tester' }

