Recursion handles the unknown depth. Print the key, then walk into the value when it is itself an object.

code:
function printTree(node, indent) {
  for (const key of Object.keys(node)) {
    const value = node[key];
    if (typeof value === "object" && value !== null) {
      console.log(indent + key + ":");
      printTree(value, indent + "  ");
    } else {
      console.log(indent + key + ": " + value);
    }
  }
}
const config = { server: { port: 3000, host: "localhost" }, retries: 2 };
printTree(config, "");

output:
server:
  port: 3000
  host: localhost
retries: 2

