A quoted value holds a space, so you have to find the quote positions and pull the inside out as one item.

code:
function splitArgs(line) {
  const first = line.indexOf(" ");
  const command = line.slice(0, first);
  const rest = line.slice(first + 1);
  const args = [];
  for (const part of rest.split(" ")) {
    if (part.startsWith("\"") && part.endsWith("\"")) {
      args.push(part.slice(1, -1));
    } else {
      args.push(part);
    }
  }
  return { command: command, args: args };
}
const parsed = splitArgs("seed --env \"local test\" --force");
console.log("command:", parsed.command);
console.log("args:", parsed.args);
console.log("arg count:", parsed.args.length);

output:
command: seed
args: [ '--env', '"local', 'test"', '--force' ]
arg count: 4

Lower-case the text, swap every run of spaces for a dash, then clean up the ends.

