Compare the version numbers one part at a time and return as soon as a part differs.

code:
function compareVersions(a, b) {
  const pa = a.replace("v", "").split(".").map(Number);
  const pb = b.replace("v", "").split(".").map(Number);
  for (let i = 0; i < pa.length; i = i + 1) {
    if (pa[i] > pb[i]) {
      return "newer";
    }
    if (pa[i] < pb[i]) {
      return "older";
    }
  }
  return "same";
}
console.log("v20.1.0 vs v18.3.0:", compareVersions("v20.1.0", "v18.3.0"));
console.log("v18.3.0 vs v18.3.0:", compareVersions("v18.3.0", "v18.3.0"));
console.log("v20.1.0 vs v20.0.9:", compareVersions("v20.1.0", "v20.0.9"));

output:
v20.1.0 vs v18.3.0: newer
v18.3.0 vs v18.3.0: same
v20.1.0 vs v20.0.9: newer

