Count each value in one pass, then collect the ones whose count is above one.

code:
function findDuplicates(list) {
  const counts = {};
  for (const item of list) {
    counts[item] = (counts[item] || 0) + 1;
  }
  const dupes = [];
  for (const item of Object.keys(counts)) {
    if (counts[item] > 1) {
      dupes.push(item + " x" + counts[item]);
    }
  }
  return dupes;
}
const packages = ["axios", "vitest", "axios", "eslint", "vitest", "axios"];
const dupes = findDuplicates(packages);
console.log("listed:", packages.length);
console.log("unique:", Object.keys(packages.filter((p, i) => packages.indexOf(p) === i)).length);
console.log("duplicates:", dupes.join(", "));

output:
listed: 6
unique: 3
duplicates: axios x3, vitest x2

A helper that wraps a step in try and catch keeps every setup step reported the same way.

code:
function runStep(label, fn) {
  try {
    fn();
    console.log("PASS " + label);
  } catch (err) {
    console.log("FAIL " + label + " -> " + err.message);
  }
}
runStep("create config", () => {
  console.log("  config written");
});
runStep("install browsers", () => {
  throw new Error("network blocked");
});
runStep("run smoke test", () => {
  console.log("  smoke test done");
});

output:
  config written
PASS create config
FAIL install browsers -> network blocked
  smoke test done
PASS run smoke test

